/** Synthetic voice saying "Testing voice to text for the story planner." — 16 kHz mono 16-bit WAV made for this check. */
const SAMPLE_WAV_BASE64 =
  "";

export const VOICE_SAMPLE_WORDS = ["testing", "voice", "text", "story", "planner"] as const;
export const VOICE_SAMPLE_MIN_WORDS = 3;

/** A fresh copy each call, so no caller can change the clip for the next check. */
export function voiceSample(): Uint8Array<ArrayBuffer> {
  return Uint8Array.from(Buffer.from(SAMPLE_WAV_BASE64, "base64"));
}

export function transcriptMatchesSample(text: string): boolean {
  const heard = new Set(text.toLowerCase().split(/[^a-z]+/));
  return VOICE_SAMPLE_WORDS.filter((word) => heard.has(word)).length >= VOICE_SAMPLE_MIN_WORDS;
}
